  "source": "def audit(events, at):
    eligible = [event for event in events if event['seen'] <= at]
    fences = {}
    selected = {}
    for event in eligible:
        key = event['key']
        selected.setdefault(key, {})
        if event['kind'] == 'fence':
            scope = (key, event['side'])
            fences[scope] = max(fences.get(scope, 0), event['through'])

    for event in eligible:
        if event['kind'] != 'ack':
            continue
        key, side = event['key'], event['side']
        epoch, digest = event['epoch'], event['digest']
        if epoch <= fences.get((key, side), 0):
            continue
        sides = selected[key]
        current = sides.get(side)
        if current is None or epoch > current[0]:
            sides[side] = (epoch, {digest})
        elif epoch == current[0]:
            current[1].add(digest)

    result = {}
    for key, sides in selected.items():
        left, right = sides.get('L'), sides.get('R')
        if not sides:
            result[key] = 'withdrawn'
        elif any(len(value[1]) > 1 for value in sides.values()):
            result[key] = 'conflict'
        elif left is None or right is None or left[0] != right[0]:
            result[key] = 'pending'
        elif left[1] != right[1]:
            result[key] = 'diverged'
        else:
            result[key] = 'verified'
    return result
",
